<!doctype html>
<html lang="en">
<head>
<meta charset="utf-8">
<meta name="viewport" content="width=device-width,initial-scale=1">
<title>Snake</title>
<style>
  :root { color-scheme: dark; }
  * { box-sizing: border-box; }
  body {
    margin: 0; min-height: 100vh; display: grid; place-items: center;
    background: radial-gradient(circle at top, #1c2940, #090d14 65%);
    font: 600 16px system-ui, sans-serif; color: #e8f2ff;
  }
  .game { width: min(92vw, 560px); text-align: center; }
  h1 { margin: 0 0 10px; letter-spacing: .12em; font-size: 1.35rem; }
  .bar {
    display: flex; justify-content: space-between; align-items: center;
    margin: 0 0 12px; padding: 0 4px; color: #b9c9dc;
  }
  #score { color: #8df5ae; font-size: 1.2rem; }
  canvas {
    width: 100%; aspect-ratio: 1; display: block; border-radius: 12px;
    background: #0b121c; border: 2px solid #33445b;
    box-shadow: 0 16px 45px #0009, inset 0 0 32px #0008;
  }
  .controls { display: flex; justify-content: center; gap: 9px; margin-top: 14px; }
  button {
    border: 1px solid #40546d; border-radius: 8px; padding: 9px 15px;
    background: #182536; color: #e8f2ff; cursor: pointer; font: inherit;
  }
  button:hover { background: #263a52; }
  #start { background: #247847; border-color: #48ad70; }
  #start:hover { background: #31985b; }
  .hint { color: #8193aa; font-size: .82rem; margin: 13px 0 0; }
</style>
</head>
<body>
<main class="game">
  <h1>SNAKE</h1>
  <div class="bar"><span>Score</span><output id="score">0</output></div>
  <canvas id="snake" width="480" height="480" aria-label="Snake game board"></canvas>
  <div class="controls">
    <button id="start" type="button">Start</button>
    <button id="pause" type="button">Pause</button>
    <button id="reset" type="button">Reset</button>
  </div>
  <p class="hint">Use arrow keys to steer</p>
</main>
<script>
(() => {
  const canvas = document.getElementById("snake");
  const ctx = canvas.getContext("2d");
  const scoreEl = document.getElementById("score");
  const CELL = 20, w = 24, h = 24;
  const vectors = { up:[0,-1], down:[0,1], left:[-1,0], right:[1,0] };
  const opposite = { up:"down", down:"up", left:"right", right:"left" };
  let body, food, direction, queued, points, isAlive, timer = null;

  function randomFood() {
    const free = [];
    for (let y = 0; y < h; y++) for (let x = 0; x < w; x++)
      if (!body.some(p => p[0] === x && p[1] === y)) free.push([x,y]);
    return free.length ? free[Math.floor(Math.random() * free.length)] : null;
  }

  function draw() {
    const s = canvas.width / w;
    ctx.clearRect(0, 0, canvas.width, canvas.height);
    ctx.fillStyle = "#0b121c"; ctx.fillRect(0, 0, canvas.width, canvas.height);
    ctx.strokeStyle = "#172536"; ctx.lineWidth = 1;
    for (let i = 1; i < w; i++) {
      ctx.beginPath(); ctx.moveTo(i*s,0); ctx.lineTo(i*s,canvas.height); ctx.stroke();
      ctx.beginPath(); ctx.moveTo(0,i*s); ctx.lineTo(canvas.width,i*s); ctx.stroke();
    }
    if (food) {
      ctx.fillStyle = "#ff5b68";
      ctx.beginPath(); ctx.arc((food[0]+.5)*s, (food[1]+.5)*s, s*.31, 0, Math.PI*2); ctx.fill();
      ctx.fillStyle = "#ff9ba3";
      ctx.beginPath(); ctx.arc((food[0]+.39)*s, (food[1]+.36)*s, s*.09, 0, Math.PI*2); ctx.fill();
    }
    body.forEach((p, i) => {
      const pad = i === 0 ? 2 : 3;
      ctx.fillStyle = i === 0 ? "#9af7b7" : "#43bd72";
      ctx.fillRect(p[0]*s+pad, p[1]*s+pad, s-pad*2, s-pad*2);
    });
    if (!isAlive) {
      ctx.fillStyle = "rgba(4,8,13,.66)"; ctx.fillRect(0,0,canvas.width,canvas.height);
      ctx.fillStyle = "#ff8790"; ctx.font = "bold 28px system-ui"; ctx.textAlign = "center";
      ctx.fillText("GAME OVER", canvas.width/2, canvas.height/2);
    }
    scoreEl.textContent = points;
  }

  function reset() {
    body = [[6,12],[5,12],[4,12]];
    direction = "right"; queued = null; points = 0; isAlive = true;
    food = randomFood(); draw();
  }

  function setDir(next) {
    if (!vectors[next] || !isAlive) return;
    if (next !== opposite[direction]) queued = next;
  }

  function tick() {
    if (!isAlive) return;
    if (queued) { direction = queued; queued = null; }
    const [dx, dy] = vectors[direction], head = body[0];
    const next = [head[0] + dx, head[1] + dy];
    const eating = food && next[0] === food[0] && next[1] === food[1];
    const collisionBody = eating ? body : body.slice(0, -1);
    if (next[0] < 0 || next[0] >= w || next[1] < 0 || next[1] >= h ||
        collisionBody.some(p => p[0] === next[0] && p[1] === next[1])) {
      isAlive = false; stop(); draw(); return;
    }
    body.unshift(next);
    if (eating) { points++; food = randomFood(); }
    else body.pop();
    draw();
  }

  function start() {
    if (!isAlive) return;
    if (!timer) timer = setInterval(tick, 120);
  }
  function stop() { if (timer) clearInterval(timer); timer = null; }

  window.game = {
    w, h, reset, tick, setDir,
    setFood(x, y) {
      if (Number.isInteger(x) && Number.isInteger(y) && x >= 0 && x < w && y >= 0 && y < h) {
        food = [x, y]; draw();
      }
    },
    snake: () => body.map(p => [p[0], p[1]]),
    food: () => food ? [food[0], food[1]] : null,
    alive: () => isAlive,
    score: () => points
  };

  document.getElementById("start").onclick = start;
  document.getElementById("pause").onclick = stop;
  document.getElementById("reset").onclick = () => { stop(); reset(); };
  window.addEventListener("keydown", e => {
    const keys = { ArrowUp:"up", ArrowDown:"down", ArrowLeft:"left", ArrowRight:"right" };
    if (keys[e.key]) { e.preventDefault(); setDir(keys[e.key]); }
  });
  reset();
})();
</script>
</body>
</html>
